<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reçu {{ $payment->reference }}</title><style>body{font:15px Arial,sans-serif;color:#254534;background:#f6f5ee;padding:40px}main{max-width:680px;margin:auto;background:white;border:1px solid #dfe5d5;padding:40px;border-radius:10px}h1{font:32px Georgia,serif}dt{color:#879477;margin-top:22px;font-size:12px}dd{margin:7px 0}button{background:#244b39;color:white;padding:13px 20px;border:0;border-radius:5px}@media print{body{background:white;padding:0}button{display:none}main{border:0}}</style></head><body><main><p>UNIVERSITÉ SIMON KIMBANGU</p><h1>Reçu de versement</h1><p>Référence : {{ $payment->reference }}</p><dl><dt>Étudiant</dt><dd>{{ $academic->profile->user->first_name }} {{ $academic->profile->user->last_name }}</dd><dt>Matricule</dt><dd>{{ $academic->matricule ?? 'Non renseigné' }}</dd><dt>Formation et année</dt><dd>{{ $academic->level->faculty->name }} · {{ $academic->level->title }} · {{ $academic->academicYear->title }}</dd><dt>Montant du versement confirmé</dt><dd>{{ number_format($payment->amount_cents / 100,2,',',' ') }} {{ $payment->currency }}</dd><dt>Confirmation comptable</dt><dd>{{ $payment->confirmed_at->timezone('Africa/Kinshasa')->format('d/m/Y à H:i') }}</dd><dt>État actuel de l’écriture</dt><dd>{{ ['confirmed'=>'Confirmé','cancelled'=>'Annulé','refunded'=>'Remboursement enregistré'][$payment->status] ?? $payment->status }}</dd></dl><p>Ce reçu concerne ce versement uniquement. Il ne constitue pas une attestation de règlement intégral des frais.</p><button onclick="window.print()">Imprimer le reçu</button></main></body></html>
